"""Bounded character-prefix-aware row and column reordering."""

import heapq
from typing import List, Tuple

import numpy as np
import pandas as pd

from solver import Algorithm


class Evolved(Algorithm):
    """Select a strong global order and a row-specific lexical-frontier order."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional frame and the most recently returned orders."""
        self.df = df
        self._last_orders = None

    @staticmethod
    def _cell_string(value) -> str:
        """Serialize one value as the evaluator does, replacing missing values by ''. """
        missing = pd.isna(value)
        if isinstance(missing, (bool, np.bool_)) and bool(missing):
            return ""
        return str(value)

    @staticmethod
    def _lcp(a: str, b: str) -> int:
        """Return the exact common-prefix length using binary-search slicing."""
        if a == b:
            return len(a)
        lo, hi = 0, min(len(a), len(b))
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if a[:mid] == b[:mid]:
                lo = mid
            else:
                hi = mid - 1
        return lo

    @classmethod
    def _score(cls, strings: List[str]) -> int:
        """Compute ideal character-Trie reuse from lexicographically adjacent rows."""
        if len(strings) < 2:
            return 0
        ordered = sorted(strings)
        return sum(cls._lcp(a, b) for a, b in zip(ordered, ordered[1:]))

    @staticmethod
    def _positions(columns):
        """Map stringified labels to their unique source positions."""
        out = {}
        for i, name in enumerate(columns):
            out.setdefault(str(name), []).append(i)
        return out

    @classmethod
    def _edges(cls, columns, dependencies, merges):
        """Create directed precedence edges for dependencies and merge adjacency."""
        pos = cls._positions(columns)
        result = []
        seen = set()

        def add(a, b):
            if a != b and (a, b) not in seen:
                seen.add((a, b))
                result.append((a, b))

        for pair in dependencies or []:
            if len(pair) == 2:
                aa = pos.get(str(pair[0]), [])
                bb = pos.get(str(pair[1]), [])
                if len(aa) == 1 and len(bb) == 1:
                    add(aa[0], bb[0])

        # Merge requests retain their input-order adjacency.
        for pair in merges or []:
            if len(pair) == 2:
                aa = pos.get(str(pair[0]), [])
                bb = pos.get(str(pair[1]), [])
                if len(aa) == 1 and len(bb) == 1:
                    add(aa[0], bb[0])
        return result

    @classmethod
    def _topological(cls, m, preference, columns, dependencies, merges):
        """Repair a preferred order with deterministic Kahn topological sorting."""
        outgoing = [[] for _ in range(m)]
        indegree = [0] * m
        for a, b in cls._edges(columns, dependencies, merges):
            outgoing[a].append(b)
            indegree[b] += 1

        rank = {x: i for i, x in enumerate(preference)}
        heap = [(rank.get(i, m + i), i) for i in range(m) if indegree[i] == 0]
        heapq.heapify(heap)
        answer = []

        while heap:
            _, node = heapq.heappop(heap)
            answer.append(node)
            for nxt in outgoing[node]:
                indegree[nxt] -= 1
                if indegree[nxt] == 0:
                    heapq.heappush(heap, (rank.get(nxt, m + nxt), nxt))

        return answer if len(answer) == m else list(preference)

    @classmethod
    def _lexical_frontier(cls, text, columns, dependencies, merges):
        """Build one legal row-specific order by choosing the smallest available cell."""
        n, m = text.shape
        outgoing = [[] for _ in range(m)]
        incoming = [[] for _ in range(m)]
        for a, b in cls._edges(columns, dependencies, merges):
            outgoing[a].append(b)
            incoming[b].append(a)

        base_indegree = [len(v) for v in incoming]
        orders = []

        for row in range(n):
            indegree = base_indegree[:]
            heap = [(text[row, j], j) for j in range(m) if indegree[j] == 0]
            heapq.heapify(heap)
            order = []

            while heap:
                _, j = heapq.heappop(heap)
                order.append(j)
                for nxt in outgoing[j]:
                    indegree[nxt] -= 1
                    if indegree[nxt] == 0:
                        heapq.heappush(heap, (text[row, nxt], nxt))

            # Cyclic constraints are invalid for a strict topological order;
            # retain all cells deterministically rather than dropping any.
            if len(order) != m:
                order = sorted(range(m), key=lambda j: (text[row, j], j))
            orders.append(order)

        return orders

    @staticmethod
    def _serialize(text, orders):
        """Serialize each source row using its selected source-column permutation."""
        return [
            "".join(text[row, col] for col in orders[row])
            for row in range(text.shape[0])
        ]

    @staticmethod
    def _materialize(df, source, orders, serialized):
        """Sort by serialized keys and copy every original cell without conversion."""
        row_order = sorted(range(len(orders)), key=lambda r: (serialized[r], r))
        values = np.empty(source.shape, dtype=object)
        public = []

        for out_row, src_row in enumerate(row_order):
            order = orders[src_row]
            values[out_row, :] = [source[src_row, j] for j in order]
            public.append([df.columns[j] for j in order])

        result = pd.DataFrame(
            values,
            index=df.index.take(row_order),
            columns=list(df.columns),
        )
        return result, public

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List]]:
        """Compare a frequency-ranked global order with one lexical-frontier candidate."""
        if not isinstance(df, pd.DataFrame):
            raise TypeError("df must be a pandas DataFrame")

        n, m = df.shape
        if n == 0 or m == 0:
            orders = [[] for _ in range(n)]
            self._last_orders = orders
            return df.copy(), orders

        source = df.to_numpy(dtype=object, copy=True)
        text = np.empty((n, m), dtype=object)
        for j in range(m):
            text[:, j] = [self._cell_string(v) for v in source[:, j]]

        # Length-weighted pair repetition is a cheap global proxy for shared prefixes.
        stats = []
        for j in range(m):
            counts = {}
            lengths = {}
            for value in text[:, j]:
                counts[value] = counts.get(value, 0) + 1
                lengths[value] = len(value)
            pair_mass = sum(lengths[v] * c * (c - 1)
                            for v, c in counts.items())
            repeat_mass = sum(lengths[v] * max(0, c - 1)
                              for v, c in counts.items())
            total = sum(lengths[v] * c for v, c in counts.items())
            stats.append((pair_mass, repeat_mass, total))

        columns = list(df.columns)
        global_order = [
            j for j, _ in sorted(
                enumerate(stats),
                key=lambda x: (-x[1][0], -x[1][1], -x[1][2], x[0]),
            )
        ]
        global_order = self._topological(
            m, global_order, columns, one_way_dep, col_merge
        )

        global_orders = [global_order[:] for _ in range(n)]
        candidates = [
            (self._score(self._serialize(text, global_orders)), global_orders)
        ]

        # The requested scouting mechanism: one bounded rowwise construction.
        if m <= 96 and n * m <= 200000:
            frontier = self._lexical_frontier(
                text, columns, one_way_dep, col_merge
            )
            candidates.append((self._score(self._serialize(text, frontier)), frontier))

        best_score, best_orders = max(candidates, key=lambda item: item[0])
        best_serialized = self._serialize(text, best_orders)
        result, public_orders = self._materialize(
            df, source, best_orders, best_serialized
        )

        if result.shape != df.shape:
            raise RuntimeError("Reordering changed DataFrame shape")

        self._last_orders = public_orders
        return result, public_orders

